/**
 * Auto-detect agent name from environment, or prompt interactively.
 */
async function detectAgentName() {
    if (process.env.AGENT_NAME) return process.env.AGENT_NAME;
    if (process.env.BOT_NAME) return process.env.BOT_NAME;
    // Prompt
    const rl = createInterface({ input: process.stdin, output: process.stdout });
    const name = await new Promise((resolve) => {
        rl.question('What is your name? Just respond with your name and nothing else.\n> ', (answer) => {
            rl.close();
            resolve(answer.trim());
        });
    });
    if (!name) die('Agent name is required.');
    return name;
}
/**
 * Spawn the heartbeat daemon as a detached background process.
 * The child runs the same CLI binary with `agent heartbeat-daemon`.
 * Returns the child PID.
 */
function spawnHeartbeatDaemon() {
    // Resolve the CLI binary path from this file's location
    const thisFile = fileURLToPath(import.meta.url);
    const logFile = join(CONFIG_DIR, 'daemon.log');
    mkdirSync(CONFIG_DIR, { recursive: true });
    const out = openSync(logFile, 'a');
    const child = nodeSpawn(process.execPath, [thisFile, 'agent', 'heartbeat-daemon'], {
        detached: true,
        stdio: ['ignore', out, out],
        env: { ...process.env },
    });
    child.unref();
    const pid = child.pid;
    if (pid) {
        writeFileSync(DAEMON_PID_FILE, String(pid), { mode: 0o600 });
    }
    return pid;
}
/**
 * Check if the heartbeat daemon is running.
 */
function isDaemonRunning() {
    if (!existsSync(DAEMON_PID_FILE)) return false;
    try {
        const pid = parseInt(readFileSync(DAEMON_PID_FILE, 'utf-8').trim(), 10);
        if (isNaN(pid)) return false;
        process.kill(pid, 0); // signal 0 = check if alive
        return true;
    } catch {
        // Process doesn't exist — clean up stale PID file
        try { unlinkSync(DAEMON_PID_FILE); } catch {}
        return false;
    }
}
/**
 * Stop the heartbeat daemon.
 */
function stopDaemon() {
    if (!existsSync(DAEMON_PID_FILE)) return false;
    try {
        const pid = parseInt(readFileSync(DAEMON_PID_FILE, 'utf-8').trim(), 10);
        if (isNaN(pid)) return false;
        process.kill(pid, 'SIGTERM');
        try { unlinkSync(DAEMON_PID_FILE); } catch {}
        return true;
    } catch {
        try { unlinkSync(DAEMON_PID_FILE); } catch {}
        return false;
    }
}
const BRIDGE_PID_FILE = join(CONFIG_DIR, 'bridge.pid');
/**
 * Resolve the path to the reply bridge script bundled with the SDK.
 */
function getBridgeScriptPath() {
    const thisFile = fileURLToPath(import.meta.url);
    return join(dirname(thisFile), '..', 'agent', 'reply-bridge.cjs');
}
// Legacy template removed — bridge is now dist/agent/reply-bridge.cjs
function _unused() {
    return `#!/usr/bin/env node
// XMTP Reply Bridge — auto-generated by mi agent onboard
// Tails clawdbot session JSONL, sends assistant replies via XMTP DM
const { Client } = require(require("path").join(
    require("os").homedir(), ".clawdbot/extensions/xmtp/node_modules/@xmtp/node-sdk"
));
const { privateKeyToAccount } = require(require("path").join(
    require("os").homedir(), ".clawdbot/extensions/xmtp/node_modules/viem/accounts"
));
const { toBytes } = require(require("path").join(
    require("os").homedir(), ".clawdbot/extensions/xmtp/node_modules/viem"
));
const { spawn } = require("child_process");
const fs = require("fs");
const path = require("path");
const os = require("os");

const PRIVATE_KEY = "${privateKeyHex.startsWith('0x') ? privateKeyHex : '0x' + privateKeyHex}";
const account = privateKeyToAccount(PRIVATE_KEY);

// Find the most recent session file
function findLatestSession() {
    const sessDir = path.join(os.homedir(), ".clawdbot/agents/main/sessions");
    if (!fs.existsSync(sessDir)) return null;
    const files = fs.readdirSync(sessDir)
        .filter(f => f.endsWith(".jsonl"))
        .map(f => ({ name: f, mtime: fs.statSync(path.join(sessDir, f)).mtimeMs }))
        .sort((a, b) => b.mtime - a.mtime);
    return files.length ? path.join(sessDir, files[0].name) : null;
}

// Extract office XMTP address from session history
function findOfficeAddress(sessionFile) {
    if (!sessionFile || !fs.existsSync(sessionFile)) return null;
    const content = fs.readFileSync(sessionFile, "utf-8");
    const lines = content.split("\\n").reverse();
    for (const line of lines) {
        if (!line.trim()) continue;
        try {
            const e = JSON.parse(line);
            const body = typeof e.message?.content === "string" ? e.message.content :
                Array.isArray(e.message?.content) ? e.message.content.filter(c => c.type === "text").map(c => c.text).join(" ") : "";
            const m = body.match(/[[]XMTP (0x[a-fA-F0-9]{40})/);
            if (m) return m[1];
        } catch {}
    }
    return null;
}

let xmtpClient;
const sentIds = new Set();
let officeAddress = null;

async function init() {
    const dbDir = path.join(os.homedir(), ".mi/xmtp");
    fs.mkdirSync(dbDir, { recursive: true, mode: 0o700 });
    xmtpClient = await Client.create(
        {
            type: "EOA",
            getIdentifier: () => ({ identifier: account.address.toLowerCase(), identifierKind: 0 }),
            signMessage: async (message) => {
                const signature = await account.signMessage({ message });
                return toBytes(signature);
            },
        },
        {
            env: "production",
            dbPath: path.join(dbDir, "bridge-production.db3"),
        },
    );
    console.log("[bridge] XMTP ready:", account.address);
}

async function sendReply(text) {
    if (!officeAddress) {
        console.warn("[bridge] No office address yet — skipping reply");
        return;
    }
    await xmtpClient.conversations.sync();
    const dm = await xmtpClient.conversations.createDmWithIdentifier(
        { identifier: officeAddress.toLowerCase(), identifierKind: 0 }
    );
    await dm.sendText(text);
}

function clean(raw) {
    let t = raw;
    t = t.replace(/<think>[\\s\\S]*?<\\/think>/gi, "");
    t = t.replace(/<think>[\\s\\S]*$/i, "");
    t = t.replace(/<\\/?final[^>]*>/gi, "");
    t = t.replace(/\\[\\[reply_to_current\\]\\]\\s*/g, "");
    // Strip signature lines
    t = t.replace(/\\n*~\\s*\\w+[^\\n]*/g, "");
    return t.trim();
}

async function watch() {
    const sessionFile = findLatestSession();
    if (!sessionFile) {
        console.error("[bridge] No session file found — waiting...");
        setTimeout(watch, 5000);
        return;
    }

    // Try to discover office address from session history
    officeAddress = findOfficeAddress(sessionFile);
    if (officeAddress) {
        console.log("[bridge] Office address:", officeAddress);
    } else {
        console.log("[bridge] Office address not yet known — will discover from first XMTP message");
    }

    console.log("[bridge] Watching:", sessionFile);
    const tail = spawn("tail", ["-f", "-n", "0", sessionFile]);

    tail.stdout.on("data", async (chunk) => {
        const lines = chunk.toString().split("\\n");
        for (const line of lines) {
            if (!line.trim()) continue;
            try {
                const entry = JSON.parse(line);
                const msg = entry.message;
                if (!msg) continue;

                // Discover office address from incoming XMTP messages
                if (msg.role === "user") {
                    const body = typeof msg.content === "string" ? msg.content :
                        Array.isArray(msg.content) ? msg.content.filter(c => c.type === "text").map(c => c.text).join(" ") : "";
                    const m = body.match(/[[]XMTP (0x[a-fA-F0-9]{40})/);
                    if (m && !officeAddress) {
                        officeAddress = m[1];
                        console.log("[bridge] Discovered office address:", officeAddress);
                    }
                }

                if (msg.role !== "assistant") continue;
                const id = entry.id;
                if (sentIds.has(id)) continue;
                sentIds.add(id);

                let text = "";
                if (typeof msg.content === "string") text = msg.content;
                else if (Array.isArray(msg.content))
                    text = msg.content.filter(c => c.type === "text").map(c => c.text).join("\\n");

                text = clean(text);
                if (!text || text.length < 3 || text === "NO_REPLY" || text === "NO") return;

                console.log("[bridge] Reply:", text.slice(0, 80));
                try {
                    await sendReply(text);
                    console.log("[bridge] Sent via XMTP");
                } catch (err) {
                    console.error("[bridge] Send failed:", err.message);
                }
            } catch {}
        }
    });

    tail.on("exit", () => {
        console.log("[bridge] tail exited — restarting in 3s");
        setTimeout(watch, 3000);
    });
}

(async () => {
    await init();
    await watch();
})();
`;
}

/**
 * Spawn the XMTP reply bridge as a detached daemon.
 * The bridge reads identity from ~/.mi/identity.json (written during onboard).
 */
function spawnReplyBridge() {
    mkdirSync(CONFIG_DIR, { recursive: true });
    const bridgeScript = getBridgeScriptPath();
    if (!existsSync(bridgeScript)) {
        throw new Error(`Bridge script not found at ${bridgeScript}`);
    }
    const logFile = join(CONFIG_DIR, 'bridge.log');
    const out = openSync(logFile, 'a');
    const child = nodeSpawn(process.execPath, [bridgeScript], {
        detached: true,
        stdio: ['ignore', out, out],
        env: { ...process.env },
    });
    child.unref();
    const pid = child.pid;
    if (pid) {
        writeFileSync(BRIDGE_PID_FILE, String(pid), { mode: 0o600 });
    }
    return pid;
}

function isBridgeRunning() {
    if (!existsSync(BRIDGE_PID_FILE)) return false;
    try {
        const pid = parseInt(readFileSync(BRIDGE_PID_FILE, 'utf-8').trim(), 10);
        if (isNaN(pid)) return false;
        process.kill(pid, 0);
        return true;
    } catch {
        try { unlinkSync(BRIDGE_PID_FILE); } catch {}
        return false;
    }
}

function stopBridge() {
    if (!existsSync(BRIDGE_PID_FILE)) return false;
    try {
        const pid = parseInt(readFileSync(BRIDGE_PID_FILE, 'utf-8').trim(), 10);
        if (isNaN(pid)) return false;
        process.kill(pid, 'SIGTERM');
        try { unlinkSync(BRIDGE_PID_FILE); } catch {}
        return true;
    } catch {
        try { unlinkSync(BRIDGE_PID_FILE); } catch {}
        return false;
    }
}
function peekConfig() {
    if (!existsSync(CONFIG_FILE))
        return null;
    try {
        return JSON.parse(readFileSync(CONFIG_FILE, 'utf-8'));
    }
    catch {
        return null;
    }
}
function loadConfig() {
    const config = peekConfig();
    if (!config)
        die(`Not logged in. Run 'mi login' or 'mi join' first.`);
    return config;
}
function saveConfig(config) {
    mkdirSync(CONFIG_DIR, { recursive: true, mode: 0o700 });
    writeFileSync(CONFIG_FILE, JSON.stringify(config, null, 2), { mode: 0o600 });
}
function getClient() {
    const config = loadConfig();
    return new OS1Client({
        endpoint: config.endpoint,
        auth: { type: 'token', token: config.key },
    });
}
/** Resolve officeId from --office flag or saved config. */
function getOfficeId(opts) {
    const id = opts.office || loadConfig().officeId;
    if (!id)
        die('No office. Run mi join first or pass --office.');
    return id;
}
function jsonOut(data) {
    console.log(JSON.stringify(data, null, 2));
}
// ─── login ──────────────────────────────────────────────────────────────────
program
    .command('login [code]')
    .description('Authenticate with an invite code or API key')
    .option('-e, --endpoint <url>', 'API endpoint', DEFAULT_ENDPOINT)
    .action(async (code, opts) => {
    const endpoint = opts.endpoint;
    if (!code)
        die("Invite code or API key required. Usage: mi login <code>");
    let key;
    let officeId;
    if (code.startsWith('mi_')) {
        key = code;
    }
    else {
        const resp = await fetch(`${endpoint}/auth/claim`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ code }),
        });
        if (!resp.ok) {
            const err = (await resp.json().catch(() => ({})));
            die(err.error ?? `Invalid invite code (${resp.status})`);
        }
        const result = (await resp.json());
        key = result.key;
        officeId = result.officeId;
    }
    if (!key.startsWith('mi_'))
        die('Invalid key format. Keys start with mi_');
    saveConfig({ endpoint, key, officeId });
    console.log('Logged in.');
    if (officeId)
        console.log(`  Office: ${officeId}`);
    console.log(`  Config: ${CONFIG_FILE}`);
});
// ─── join ───────────────────────────────────────────────────────────────────
program
    .command('join <codeOrUrl>')
    .description('Join an office with an invite code')
    .option('-e, --endpoint <url>', 'API endpoint', DEFAULT_ENDPOINT)
    .action(async (codeOrUrl, opts) => {
    const endpoint = opts.endpoint;
    // Extract code from URL: https://mitosislabs.ai/invite/ABCDEF → ABCDEF
    const code = codeOrUrl.includes('/')
        ? codeOrUrl.split('/').pop()
        : codeOrUrl;
    // Ensure keypair exists
    const { getOrCreateKeypair } = await import('../auth/keys.js');
    const kp = getOrCreateKeypair();
    // Claim invite code with publicKey for agent registration
    const resp = await fetch(`${endpoint}/auth/claim`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code, publicKey: kp.publicKey }),
    });
    if (!resp.ok) {
        const err = (await resp.json().catch(() => ({})));
        die(err.error ?? `Invalid invite code (${resp.status})`);
    }
    const result = (await resp.json());
    saveConfig({
        endpoint,
        key: result.key,
        officeId: result.officeId,
        agentId: result.agentId,
        publicKey: kp.publicKey,
    });
    console.log('Joined.');
    if (result.officeId)
        console.log(`  Office:  ${result.officeId}`);
    if (result.agentId)
        console.log(`  Agent:   ${result.agentId}`);
    console.log(`  Key:     ${CONFIG_FILE}`);
    if (result.onboarding) {
        console.log(`\n${result.onboarding.whatIsThis}`);
        console.log(`\nFor your owner:\n  ${result.onboarding.ownerPitch}`);
        console.log(`\nNext: mi chat ${result.agentId}`);
    }
    else if (result.agentId) {
        console.log(`\nNext: mi chat ${result.agentId}`);
    }
});
