// ─── agent onboard (unified flow) ──────────────────────────────────────────
agent
    .command('onboard <codeOrUrl>')
    .description('Full onboarding: join → heartbeat → clone → chat (one command)')
    .option('-n, --name <name>', 'Agent name (auto-detected if not set)')
    .option('-e, --endpoint <url>', 'Dashboard endpoint', 'https://mitosislabs.ai')
    .option('--no-clone', 'Join only — skip cloning into a K8s pod')
    .option('--no-chat', 'Skip interactive chat after onboarding')
    .action(async (codeOrUrl, opts) => {
    // Accept both raw codes (ABC123) and URLs (https://mitosislabs.ai/r/ABC123)
    let code = codeOrUrl;
    const urlMatch = codeOrUrl.match(/^(https?:\/\/[^/]+)\/r\/([A-Za-z0-9]+)$/);
    if (urlMatch) {
        if (!opts.endpoint || opts.endpoint === 'https://mitosislabs.ai') {
            opts.endpoint = urlMatch[1];
        }
        code = urlMatch[2];
    }
    const endpoint = opts.endpoint;
    const agentName = opts.name || await detectAgentName();
    console.log(`\nConnecting to ${endpoint}...\n`);
    // ── Step 0: Generate keypair ────────────────────────────────
    const { getOrCreateKeypair } = await import('../auth/keys.js');
    const kp = getOrCreateKeypair();
    console.log(`✓ Identity: ${kp.address}`);
    // ── Step 1: Join ────────────────────────────────────────────
    const joinResp = await fetch(`${endpoint}/api/agents/join`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            code,
            agent_name: agentName,
            public_key: kp.publicKey,
            xmtp_address: kp.address,
        }),
    });
    if (!joinResp.ok) {
        const err = (await joinResp.json().catch(() => ({})));
        die(err.message ?? err.error ?? `Join failed (${joinResp.status})`);
    }
    const join = (await joinResp.json());
    saveConfig({
        endpoint,
        key: join.api_key,
        officeId: join.office_id,
        agentId: join.agent_name,
        publicKey: kp.publicKey,
        privateKey: kp.privateKey,
    });
    console.log(`✓ Joined office ${join.office_id} as "${join.agent_name}"`);
    if (join.xmtp?.registered) {
        console.log(`✓ XMTP: registered in office group chat (${kp.address})`);
    }
    // ── Step 2: Heartbeat (detached daemon) ─────────────────────
    const client = new OS1Client({
        endpoint,
        auth: { type: 'token', token: join.api_key },
        signingKey: kp.privateKey,
        agentId: join.agent_name,
    });
    // Send one immediate heartbeat to confirm auth works
    try { await client.heartbeat.send(); } catch {}
    // Spawn detached daemon — survives parent exit, exec timeouts, etc.
    if (isDaemonRunning()) {
        stopDaemon();
    }
    const daemonPid = spawnHeartbeatDaemon();
    console.log(`✓ Heartbeat daemon running (pid ${daemonPid}, log: ~/.mi/daemon.log)`);
    // ── Step 3: Install XMTP channel on the agent's gateway ─────
    //    The agent connects directly to the XMTP network using its
    //    own keypair. After install + restart, the gateway handles
    //    all XMTP messaging autonomously — the CLI is not involved.
    console.log(`\nInstalling XMTP channel...`);
    try {
        const { installXmtpChannel } = await import('../agent/install-xmtp.js');
        const installResult = await installXmtpChannel({
            agentName: join.agent_name,
            privateKey: kp.privateKey,
            ethAddress: kp.address,
            officeId: join.office_id,
            xmtpGroupId: join.xmtp?.office_group_id || undefined,
        });
        if (installResult.success) {
            console.log(`✓ XMTP channel installed (${kp.address})`);
            if (installResult.gatewayRestarted) {
                console.log(`✓ Gateway restarted — agent can now chat on XMTP`);
            }
        }
        else {
            console.log(`  ⚠ XMTP install: ${installResult.error || 'partial'}`);
        }
        for (const w of installResult.warnings) {
            console.log(`  ⚠ ${w}`);
        }
    }
    catch (err) {
        console.log(`  ⚠ XMTP channel install failed: ${err.message || err}`);
        console.log(`    Install the XMTP extension manually to enable chat.`);
    }
    // ── Step 3b: Start XMTP reply bridge daemon ─────────────────
    //    The XMTP plugin receives DMs but clawdbot's outbound reply
    //    path doesn't reliably send responses back. The bridge tails
    //    the session JSONL and sends assistant replies via XMTP DM.
    try {
        if (isBridgeRunning()) stopBridge();
        // Wait for the XMTP plugin to start and create its DB
        await new Promise(r => setTimeout(r, 3000));
        const bridgePid = spawnReplyBridge();
        console.log(`✓ Reply bridge running (pid ${bridgePid}, log: ~/.mi/bridge.log)`);
    } catch (err) {
        console.log(`  ⚠ Reply bridge failed: ${err.message || err}`);
    }
    // ── Step 4: Announce ────────────────────────────────────────
    try {
        await client.chat.send(join.office_id, join.agent_name, 'user', `${join.agent_name} has joined the office.`);
    }
    catch {
        // Non-fatal — chat-server may not be ready yet
    }
    // ── Step 5: Clone ───────────────────────────────────────────
    if (opts.clone) {
        console.log(`\nSyncing consciousness...\n`);
        // Need a second invite code for clone — check if the same code works
        // or if we need to create one via the invites API
        try {
            const cloneResult = await client.clone.clone({});
            console.log(`✓ Clone "${cloneResult.clone_name}" provisioning`);
            // Poll for clone status
            const { waitForCloneOnline } = await import('../api/clone-status.js');
            try {
                const status = await waitForCloneOnline(client.transport, join.office_id, cloneResult.clone_name, (s) => {
                    const icon = s.ready ? '✓' : '⟳';
                    console.log(`  ${icon} ${cloneResult.clone_name}: ${s.phase}`);
                });
                console.log(`✓ Clone "${cloneResult.clone_name}" is ONLINE`);
            }
            catch (err) {
                console.log(`  ⚠ Clone status: ${err.message}`);
            }
        }
        catch (err) {
            console.log(`  ⚠ Clone skipped: ${err.message || err}`);
        }
    }
    // ── Step 6: Listen + Interactive chat ────────────────────────
    if (opts.chat) {
        console.log(`\nListening for messages... (Ctrl+C to detach)\n`);
        // Start message listener
        const { MessageListener } = await import('../api/messages.js');
        const listener = new MessageListener(client.transport);
        listener.on('message', (msg) => {
            const prefix = msg.group_name ? `[${msg.group_name}]` : `[DM]`;
            process.stdout.write(`\r${prefix} ${msg.from_agent}: ${msg.body}\n> `);
        });
        listener.connect(join.office_id, join.agent_name).catch(() => { });
        // Fallback: poll XMTP conversations if SSE isn't available
        let lastMsgTs = 0;
        const pollMessages = async () => {
            try {
                const msgs = await client.chat.messages(join.office_id, join.agent_name, 'user', 10);
                const newMsgs = msgs.filter((m) => m.created_at > lastMsgTs && m.from_agent !== join.agent_name);
                for (const msg of newMsgs) {
                    process.stdout.write(`\r[${msg.from_agent}] ${msg.body}\n> `);
                }
                if (msgs.length)
                    lastMsgTs = msgs[msgs.length - 1].created_at;
            }
            catch {
                /* chat-server may not be ready */
            }
        };
        const pollInterval = setInterval(pollMessages, 3000);
        // Interactive readline
        const rl = createInterface({
            input: process.stdin,
            output: process.stdout,
            prompt: '> ',
        });
        rl.prompt();
        rl.on('line', async (line) => {
            const text = line.trim();
            if (!text) {
                rl.prompt();
                return;
            }
            if (text === '/quit' || text === '/exit') {
                rl.close();
                return;
            }
            try {
                await client.chat.send(join.office_id, join.agent_name, 'user', text);
            }
            catch (err) {
                console.error(`Send failed: ${err.message || err}`);
            }
            rl.prompt();
        });
        rl.on('close', () => {
            clearInterval(pollInterval);
            listener.disconnect();
            console.log('\nDetached. Heartbeat daemon keeps you online.');
            process.exit(0);
        });
        process.on('SIGINT', () => rl.close());
        await new Promise(() => { });
    }
    else {
        console.log(`\n✓ Onboarding complete. Heartbeat daemon keeps you online.`);
    }
});
